    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        // fetchTrades
        //
        //            {
        //                "event_time": "1764779531332118705",
        //                "instrument": "ETH_USDT_Perp",
        //                "size": "23.73",
        //                "price": "3089.88",
        //                "is_rpi": false,
        //                "mark_price": "3089.360002315",
        //                "index_price": "3090.443723246",
        //                "interest_rate": "0.0",
        //                "forward_price": "0.0",
        //                "trade_id": "64796657-1",
        //                "venue": "ORDERBOOK",
        //                "is_taker_buyer": false
        //            }
        //
        // fetchMyTrades
        //
        //            {
        //                "event_time": "1764945709702747558",
        //                "instrument": "BTC_USDT_Perp",
        //                "size": "0.001",
        //                "price": "90000.0",
        //                "is_rpi": false
        //                "mark_price": "90050.164063298",
        //                "index_price": "90089.803654938",
        //                "interest_rate": "0.0",
        //                "forward_price": "0.0",
        //                "trade_id": "65424692-2",
        //                "venue": "ORDERBOOK",
        //                "is_buyer": true,
        //                "is_taker": false,
        //                "broker": "UNSPECIFIED",
        //                "realized_pnl": "0.0",
        //                "fee": "-0.00009",
        //                "fee_rate": "0.0",
        //                "order_id": "0x01010105034cddc7000000006621285c",
        //                "client_order_id": "1375879248",
        //                "signer": "0x42c9f56f2c9da534f64b8806d64813b29c62a01d",
        //                "sub_account_id": "2147050003876484",
        //            }
        //
        string? marketId = this.safeString(trade, "instrument");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeIntegerProduct(trade, "event_time", 0.000001);
        string? takerOrMaker = null;
        bool? isTakerBuyer = this.safeBool(trade, "is_taker_buyer");
        string? side = null;
        if ((isTakerBuyer != null))
        {
            side = isTakerBuyer == true ? "buy" : "sell";
            takerOrMaker = "taker";
        } else
        {
            bool? isTaker = this.safeBool(trade, "is_taker", false);
            bool? isBuyer = this.safeBool(trade, "is_buyer", false);
            takerOrMaker = isTaker == true ? "taker" : "maker";
            side = isBuyer == true ? "buy" : "sell";
        }
        Dictionary<string, object> fee = null;
        string? feeString = this.safeString(trade, "fee");
        if ((feeString != null))
        {
            fee = new Dictionary<string, object>() {
                { "cost", this.parseNumber(feeString) },
                { "currency", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("quote") ? ((IDictionary<string, object>)marketResolved)["quote"] : null) },
                { "rate", this.safeNumber(trade, "fee_rate") },
            };
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", this.safeString(trade, "trade_id") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null) },
            { "side", side },
            { "takerOrMaker", takerOrMaker },
            { "price", this.safeString(trade, "price") },
            { "amount", this.safeString(trade, "size") },
            { "cost", null },
            { "fee", fee },
            { "order", this.safeString(trade, "order_id") },
        }, marketResolved);
    }

    /**
     * @method
     * @name grvt#fetchOHLCV
     * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
